function isCardNumberValid(cardNumber: string): boolean {
  return cardNumber.length === 16;
}

function isCvvValid(cvv: string): boolean {
  return cvv.length === 3 || cvv.length === 4;
}

function isExpiryDateValid(expiryDate: string): boolean {
  const expiryRegex = /^(0[1-9]|1[0-2])\/\d{2}$/;
  if (!expiryRegex.test(expiryDate)) {
    return false;
  }

  const [month, year] = expiryDate.split('/');
  const expiryDateObj = new Date(2000 + parseInt(year, 10), parseInt(month, 10) - 1);

  return expiryDateObj >= new Date();
}

function validatePaymentDetails(payment: PaymentDetails): boolean {
  const { cardNumber, expiryDate, cvv } = payment;

  return isCardNumberValid(cardNumber) && 
         isCvvValid(cvv) && 
         isExpiryDateValid(expiryDate);
}

