interface PricingConfig {
  basePrice: number;
  taxRate: number;
  processingFeeRate: number;
}

const PRICING_CONFIG: Record<'premium' | 'enterprise', PricingConfig> = {
  premium: { basePrice: 9.99, taxRate: 0.08, processingFeeRate: 0.029 },
  enterprise: { basePrice: 49.99, taxRate: 0.08, processingFeeRate: 0.029 }
};

function calculateSubscriptionPrice(tier: 'premium' | 'enterprise'): number {
  const config = PRICING_CONFIG[tier];
  const tax = config.basePrice * config.taxRate;
  const fee = config.basePrice * config.processingFeeRate;

  return config.basePrice + tax + fee;
}

